test('moves migrate ordering, preserve task data and filters, and enforce active destinations', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-moves-'));
  let server;
  try {
    const dbPath = join(directory, 'workboard.sqlite');
